mapper.select:
select

gp.P_Id as pId,
dep.D_Name as dName,
con.Con_Name as conName,
gt.Task_End_T_Code as taskEndTCode,
mn.*
from Gantt_Tasks_Process mn
left join Gantt_Tasks gt on mn.Task_Id=gt.Task_Id
left join Gantt_Plan gp on gt.Plan_Id=gp.Plan_Id
left join Pre_Project pro on pro.P_Id=gp.P_Id

left join Con_Contract con on con.Con_Id=gp.Con_Id
left join SYS_Department dep on dep.D_Id=gp.Plan_D_Id

    1=1
    
        and mn.Task_Id=#{params.taskId}
    
    
        and gp.Con_Id=#{params.conId}
    
    
        and gp.P_Id=#{params.pId}
    
    
        and gp.Plan_D_Id=#{params.planDId}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Gtp_Create_Time desc

mapper.sql:

    and gp.Plan_Type = #{params.planType}


    and gp.Plan_Name like concat('%',#{params.planName},'%')


    and mn.Gtp_Date > #{params.gtpDateStart}


    and mn.Gtp_Date < #{params.gtpDateEnd}


    and gp.Plan_Id in
    
        #{planId}
    

and gp.P_Id in

    #{pId}
